from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == background and row[c-1] == row[c+1] and row[c-1] != background:
                out[r][c] = 2
    return out

